let _markdown = "\n\nUsage [#usage]\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm install fumadocs-typescript\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add fumadocs-typescript\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add fumadocs-typescript\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add fumadocs-typescript\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nUI Integration [#ui-integration]\n\n<FeedbackBlock id=\"bc4083a07fca4be2\" body=\"It comes with the AutoTypeTable component. Learn more about Auto Type Table.\">\n  It comes with the `AutoTypeTable` component. Learn more about [Auto Type Table](/docs/ui/components/auto-type-table).\n</FeedbackBlock>\n\nMDX Integration [#mdx-integration]\n\n<FeedbackBlock id=\"4c8dd5cae850c801\" body=\"You can use it as a remark plugin:\">\n  You can use it as a remark plugin:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Fumadocs MDX\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Fumadocs MDX\">\n      Fumadocs MDX\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"MDX Compiler\">\n      MDX Compiler\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Fumadocs MDX\">\n    ```ts title=\"source.config.ts\" \n    import {\n      remarkAutoTypeTable,\n      createGenerator,\n      createFileSystemGeneratorCache,\n    } from 'fumadocs-typescript';\n    import { defineConfig } from 'fumadocs-mdx/config';\n\n    const generator = createGenerator({\n      // recommended: choose a directory for cache\n      cache: createFileSystemGeneratorCache('.next/fumadocs-typescript'),\n    });\n\n    export default defineConfig({\n      mdxOptions: {\n        remarkPlugins: [[remarkAutoTypeTable, { generator }]],\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"MDX Compiler\">\n    ```ts\n    import {\n      remarkAutoTypeTable,\n      createGenerator,\n      createFileSystemGeneratorCache,\n    } from 'fumadocs-typescript';\n    import { compile } from '@mdx-js/mdx';\n\n    const generator = createGenerator({\n      // recommended: choose a directory for cache\n      cache: createFileSystemGeneratorCache('.next/fumadocs-typescript'),\n    });\n\n    await compile('...', {\n      remarkPlugins: [[remarkAutoTypeTable, { generator }]],\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"5be2fe7193eb3119\" body=\"It gives you a auto-type-table component.\">\n  It gives you a `auto-type-table` component.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"ea133ff3e613785a\" body=\"You can use it like Auto Type Table, but with additional rules:\">\n  You can use it like [Auto Type Table](/docs/ui/components/auto-type-table), but with additional rules:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"dc43e46600947ae9\" body=\"The value of attributes must be string.path accepts a path relative to the MDX file itself.You also need to add TypeTable to MDX components.\">\n  * The value of attributes must be string.\n  * `path` accepts a path relative to the MDX file itself.\n  * You also need to add [`TypeTable`](/docs/ui/components/type-table) to MDX components.\n</FeedbackBlock>\n\n```ts title=\"path/to/file.ts\"\nexport interface MyInterface {\n  name: string;\n}\n```\n\n```mdx title=\"page.mdx\"\n<auto-type-table path=\"./path/to/file.ts\" name=\"MyInterface\" />\n```\n\nAnnotations [#annotations]\n\nHide [#hide]\n\n<FeedbackBlock id=\"7064a0f1ec9d4905\" body=\"Hide a field by adding @internal tsdoc tag.\">\n  Hide a field by adding `@internal` tsdoc tag.\n</FeedbackBlock>\n\n```ts\ninterface MyInterface {\n  /**\n   * @internal\n   */\n  cache: number;\n}\n```\n\nSimplified Type [#simplified-type]\n\n<FeedbackBlock id=\"8ceffa62ae7ab2d6\" body=\"You can specify the simplified name of a type with the @remarks tsdoc tag.\">\n  You can specify the simplified name of a type with the `@remarks` tsdoc tag.\n</FeedbackBlock>\n\n```ts\ninterface MyInterface {\n  /**\n   * @remarks `timestamp` Returned by API. // [!code highlight]\n   */\n  time: number;\n}\n```\n\n<FeedbackBlock id=\"a884e8339632485a\" body=\"This will make the type of time property to be shown as timestamp.\">\n  This will make the type of `time` property to be shown as `timestamp`.\n</FeedbackBlock>\n\nFull type [#full-type]\n\n<FeedbackBlock id=\"4e85fa6618b3a321\" body=\"You can specify the full name of a type with the @fumadocsType tsdoc tag.\">\n  You can specify the full name of a type with the `@fumadocsType` tsdoc tag.\n</FeedbackBlock>\n\n```ts\ninterface MyInterface {\n  /**\n   * @fumadocsType `MyBeautifulClient` // [!code highlight]\n   */\n  client: MyClient;\n}\n```\n";
